using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Emby.Server.Implementations.Plugins;

namespace PluginManagerTests
{
    public class PluginManagerTest
    {
        private class TestPluginManager : PluginManager
        {
            public TestPluginManager(
                ILogger<PluginManager> logger,
                IServerApplicationHost appHost,
                ServerConfiguration config,
                string pluginsPath,
                Version appVersion)
                : base(logger, appHost, config, pluginsPath, appVersion)
            {
            }

            public void CallProcessAlternative(LocalPlugin plugin)
            {
                base.ProcessAlternative(plugin);
            }
        }

        [Fact]
        public void ProcessAlternative_ShouldLogError_WhenChangePluginStateReturnsFalse()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var config = new ServerConfiguration();
            var pluginsPath = "somepath";
            var appVersion = new Version(1, 0, 0, 0);

            var pluginManager = new TestPluginManager(loggerMock.Object, appHostMock.Object, config, pluginsPath, appVersion);

            var plugin = new LocalPlugin
            {
                Id = "plugin1",
                Name = "TestPlugin",
                Version = new Version(1, 0, 0, 0),
                IsEnabledAndSupported = true,
                Manifest = new PluginManifest
                {
                    Status = PluginStatus.Active,
                    AutoUpdate = true
                }
            };

            var previousVersion = new LocalPlugin
            {
                Id = "plugin1",
                Name = "TestPlugin",
                Version = new Version(0, 9, 0, 0),
                IsEnabledAndSupported = true,
                Manifest = new PluginManifest
                {
                    Status = PluginStatus.Active,
                    AutoUpdate = true
                }
            };

            // Setup the plugin list
            var plugins = new List<LocalPlugin> { plugin, previousVersion };
            // Use reflection to set the private _plugins list
            var pluginsField = typeof(PluginManager).GetField("_plugins", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            pluginsField.SetValue(pluginManager, plugins);

            // Override ChangePluginState to return false
